1	import { MagneticCornerTracker } from "../components/Button.js";
2	import { BlockOverlay } from "./BlockOverlay.js";
3	import { TextReveal } from "../animation/TextReveal.js";
4	import { DOM_CONFIG, MASKING, STATE_CLASSES } from "../config/dom.config.js";
5	import {
6	  MASKING_ANIM,
7	  DRAWER_ANIM,
8	  DRAWER_CLASSES,
9	} from "../config/component.config.js";
10	import { UI } from "../ui/UI.js";
11	import { Aria } from "../utils/Aria.js";
12	import type { DrawerConfig } from "../types/dom.types.js";
13	import type { MagneticCornerGsap } from "../types/component.types.js";
14	import type {
15	  GsapGlobal,
16	  GsapTweenLike,
17	  WindowWithGsap,
18	} from "../types/gsap.types.js";
19	import type { ITimelineActionTarget } from "../types/engine.types.js";
20	import { drawer } from "../core/setup.js";
21	
22	const activeTweens = new WeakMap<
23	  HTMLElement,
24	  { open?: GsapTweenLike; close?: GsapTweenLike }
25	>();
26	function getGsap(): GsapGlobal | undefined {
27	  return (window as WindowWithGsap).gsap;
28	}
29	
30	export class Drawer extends UI implements ITimelineActionTarget {
31	  private static _lockReleases = new WeakMap<HTMLElement, () => void>();
32	  declare config: DrawerConfig;
33	
34	  private _triggerSelector: string | undefined;
35	  private _revealGroups: string[] | undefined;
36	  private _triggerEl: HTMLButtonElement | null = null;
37	  private _magneticCorner: MagneticCornerTracker | null = null;
38	  private _boundFlipVisibility: () => void;
39	  private _boundKeydown: (e: KeyboardEvent) => void;
40	
41	  static getInstance(options: Partial<DrawerConfig> = {}): Drawer {
42	    const selector = options.selector ?? DOM_CONFIG.drawer.selector;
43	    return UI.getOrCreate(Drawer, { ...options, selector });
44	  }
45	
46	  constructor(config: DrawerConfig = { selector: DOM_CONFIG.drawer.selector }) {
47	    const selector = config.selector ?? DOM_CONFIG.drawer.selector;
48	    super({ ...config, selector });
49	    this._triggerSelector = config.triggerSelector;
50	    this._revealGroups = config.revealGroups ?? DOM_CONFIG.drawer.revealGroups;
51	    this._boundFlipVisibility = this._flipVisibility.bind(this);
52	    this._boundKeydown = this._onKeydown.bind(this);
53	    this.updateOptions(config);
54	  }
55	
56	  override updateOptions(config: Partial<DrawerConfig>): void {
57	    super.updateOptions(config);
58	    if (config.triggerSelector !== undefined) {
59	      this._triggerSelector = config.triggerSelector;
60	    }
61	    if (config.revealGroups !== undefined) {
62	      this._revealGroups = config.revealGroups;
63	    } else {
64	      this._revealGroups = DOM_CONFIG.drawer.revealGroups;
65	    }
66	  }
67	
68	  protected override applyVisibility(visible: boolean): void {
69	    if (visible) {
70	      this._show();
71	      return;
72	    }
73	    this._hide();
74	  }
75	
76	  readonly timelineKey = drawer;
77	
78	  getTimelineCallback(vars: Record<string, unknown>): (() => void) | null {
79	    if (typeof vars.visible === "boolean") {
80	      return vars.visible
81	        ? () => this.setVisibleOn()
82	        : () => this.setVisibleOff();
83	    }
84	    if (vars.show) return () => this.setVisibleOn();
85	    if (vars.hide) return () => this.setVisibleOff();
86	    return null;
87	  }
88	
89	  override init(): void {
90	    super.init();
91	  }
92	
93	  protected mount(): void {
94	    if (this.isDisposed) return;
95	    const root = this.getElement();
96	    if (!root) return;
97	
98	    this._mountTrigger(root);
99	    document.addEventListener("keydown", this._boundKeydown);
100	    this._mountMagneticCorner(root);
101	  }
102	
103	  private _mountTrigger(root: HTMLElement): void {
104	    if (!this._triggerSelector) return;
105	    const trigger = document.querySelector<HTMLButtonElement>(
106	      this._triggerSelector,
107	    );
108	    if (!trigger) return;
109	    this._triggerEl = trigger;
110	    trigger.addEventListener("click", this._boundFlipVisibility);
111	    this._syncAria(root.classList.contains("is-open"));
112	  }
113	
114	  private _mountMagneticCorner(root: HTMLElement): void {
115	    const gsap = getGsap();
116	    if (!gsap || typeof gsap.killTweensOf !== "function") return;
117	    this._magneticCorner = MagneticCornerTracker.createForDrawer(
118	      root,
119	      gsap as MagneticCornerGsap,
120	    );
121	  }
122	
123	  private _syncAria(isVisible: boolean): void {
124	    Aria.setExpanded(this._triggerEl, isVisible);
125	    Aria.setControls(this._triggerEl, this.element?.id ?? "drawer-panel");
126	    Aria.setHidden(this.element ?? null, !isVisible);
127	  }
128	
129	  private _onKeydown(e: KeyboardEvent): void {
130	    if (e.key !== "Escape") return;
131	    if (!this.element?.classList.contains("is-open")) return;
132	    this.setVisibleOff();
133	  }
134	
135	  private _show(): void {
136	    if (!this.element) return;
137	    this.element.classList.add("is-open");
138	    this._syncAria(true);
139	    this._visible = true;
140	  }
141	
142	  private _hide(): void {
143	    if (!this.element) return;
144	    this.element.classList.remove("is-open");
145	    this._syncAria(false);
146	    this._visible = false;
147	  }
148	
149	  private _flipVisibility(): void {
150	    if (!this.element) return;
151	    const isVisible = this.element.classList.toggle("is-open");
152	    this._syncAria(isVisible);
153	    this._visible = isVisible;
154	  }
155	
156	  override getVisibleState(): boolean {
157	    return this.element?.classList.contains("is-open") ?? false;
158	  }
159	
160	  override animateIn(): void {
161	    if (!this.element || !this._triggerEl) return;
162	    Drawer.runOpenTransition(
163	      this.element,
164	      this._triggerEl,
165	      "is-open",
166	      this._revealGroups,
167	    );
168	  }
169	
170	  override animateOut(): void {
171	    if (!this.element || !this._triggerEl) return;
172	    const header = document.querySelector<HTMLElement>("#main-header");
173	    Drawer.runCloseTransition(
174	      this.element,
175	      this._triggerEl,
176	      header,
177	      "is-open",
178	      () => undefined,
179	    );
180	  }
181	
182	  static runOpenTransition(
183	    drawer: HTMLElement,
184	    _trigger: HTMLButtonElement,
185	    _openClass: string,
186	    revealGroups?: string[],
187	    onTransitionDone?: () => void,
188	  ): void {
189	    const inner = drawer.querySelector<HTMLElement>(
190	      DOM_CONFIG.drawer.innerSelector,
191	    );
192	    const bag = activeTweens.get(drawer) ?? {};
193	    bag.open?.kill?.();
194	    bag.close?.kill?.();
195	    activeTweens.set(drawer, bag);
196	
197	    drawer.style.opacity = "";
198	    drawer.classList.remove(DRAWER_CLASSES.textRevealReady);
199	    drawer.classList.add(STATE_CLASSES.animatingIn);
200	
201	    (async () => {
202	      await BlockOverlay.playIn();
203	      drawer.classList.remove(STATE_CLASSES.animatingIn);
204	      drawer.style.opacity = "1";
205	      if (inner) {
206	        inner.style.opacity = "1";
207	        inner.style.transform = "translateY(0)";
208	      }
209	      await BlockOverlay.playOut();
210	      drawer.classList.add(DRAWER_CLASSES.textRevealReady);
211	      setTimeout(
212	        () =>
213	          Drawer.revealMaskingInOrder(
214	            drawer,
215	            revealGroups ?? DOM_CONFIG.drawer.revealGroups,
216	          ),
217	        DRAWER_ANIM.openMaskingDelayMs,
218	      );
219	    })()
220	      .catch(() => {
221	      })
222	      .finally(() => {
223	        onTransitionDone?.();
224	      });
225	  }
226	
227	  static runCloseTransition(
228	    drawer: HTMLElement,
229	    trigger: HTMLButtonElement,
230	    header: HTMLElement | null,
231	    openClass: string,
232	    onComplete: () => void,
233	    onTransitionDone?: () => void,
234	  ): void {
235	    const bag = activeTweens.get(drawer) ?? {};
236	    bag.open?.kill?.();
237	    bag.close?.kill?.();
238	    drawer.style.opacity = "";
239	    activeTweens.set(drawer, bag);
240	
241	    drawer.classList.remove(DRAWER_CLASSES.textRevealReady);
242	    TextReveal.setVisibleOff(drawer);
243	
244	    (async () => {
245	      await new Promise<void>((r) =>
246	        window.setTimeout(r, MASKING_ANIM.textOutMs),
247	      );
248	
249	      await BlockOverlay.playIn();
250	
251	      if (drawer.contains(document.activeElement)) trigger.focus();
252	      drawer.classList.remove(openClass);
253	      trigger.classList.remove(openClass);
254	      header?.classList.remove(openClass);
255	      Aria.setExpanded(trigger, false);
256	      Aria.setHidden(drawer, true);
257	      Aria.setExpanded(header ?? null, false);
258	      Drawer.releaseLock(drawer);
259	      onComplete();
260	
261	      await BlockOverlay.playOut();
262	    })()
263	      .catch(() => {
264	      })
265	      .finally(() => {
266	        onTransitionDone?.();
267	      });
268	  }
269	
270	  private static revealMaskingInOrder(
271	    drawer: HTMLElement,
272	    groups: string[],
273	  ): void {
274	    let delay = 0;
275	
276	    for (const groupSel of groups) {
277	      const items = Array.from(
278	        drawer.querySelectorAll<HTMLElement>(`${groupSel} ${MASKING.selector}`),
279	      );
280	      items.forEach((el) => {
281	        setTimeout(() => TextReveal.setVisibleOn(el), delay);
282	        delay += MASKING_ANIM.staggerMs;
283	      });
284	      delay += MASKING_ANIM.groupGapMs;
285	    }
286	  }
287	
288	  static runTextOutOnly(
289	    drawerPanel: HTMLElement,
290	    _trigger: HTMLButtonElement,
291	    _header: HTMLElement | null,
292	    _openClass: string,
293	  ): Promise<void> {
294	    TextReveal.setVisibleOff(drawerPanel);
295	    drawerPanel.classList.add(STATE_CLASSES.barbaLeaving);
296	    return new Promise<void>((resolve) => {
297	      window.setTimeout(() => resolve(), MASKING_ANIM.textOutMs);
298	    });
299	  }
300	
301	  static runTextOutThenClose(
302	    drawerPanel: HTMLElement,
303	    trigger: HTMLButtonElement,
304	    header: HTMLElement | null,
305	    openClass: string,
306	  ): Promise<void> {
307	    TextReveal.setVisibleOff(drawerPanel);
308	    drawerPanel.classList.add(STATE_CLASSES.barbaLeaving);
309	
310	    return new Promise<void>((resolve) => {
311	      window.setTimeout(() => {
312	        drawerPanel.classList.remove(STATE_CLASSES.barbaLeaving);
313	        if (
314	          document.activeElement &&
315	          drawerPanel.contains(document.activeElement)
316	        ) {
317	          trigger.focus();
318	        }
319	        drawerPanel.classList.remove(openClass);
320	        Aria.setHidden(drawerPanel, true);
321	        Drawer.releaseLock(drawerPanel);
322	        trigger.classList.remove(openClass);
323	        Aria.setExpanded(trigger, false);
324	        header?.classList.remove(openClass);
325	        Aria.setExpanded(header ?? null, false);
326	        const h = trigger.closest("header");
327	        if (h?.classList.contains(openClass)) {
328	          h.classList.remove(openClass);
329	          Aria.setExpanded(h, false);
330	        }
331	        resolve();
332	      }, MASKING_ANIM.textOutMs);
333	    });
334	  }
335	
336	  static syncNavActiveState(): void {
337	    const currentPath = window.location.pathname || "/";
338	
339	    const setActive = (link: HTMLAnchorElement): void => {
340	      const href = link.getAttribute("href");
341	      if (href == null) return;
342	      const hrefPath = href.startsWith("http") ? new URL(href).pathname : href;
343	      const isActive =
344	        hrefPath === "/"
345	          ? currentPath === "/" || currentPath === ""
346	          : currentPath === hrefPath ||
347	            currentPath.startsWith(hrefPath.replace(/\/$/, "") + "/");
348	      link.classList.toggle(DRAWER_CLASSES.linkActive, isActive);
349	    };
350	
351	    document
352	      .querySelectorAll<HTMLAnchorElement>(DOM_CONFIG.drawer.gnbLinkSelector)
353	      .forEach((el) => setActive(el));
354	    document
355	      .querySelectorAll<HTMLAnchorElement>(DOM_CONFIG.drawer.gnbSubLinkSelector)
356	      .forEach((el) => setActive(el));
357	  }
358	
359	  static attachLock(drawer: HTMLElement, release: () => void): void {
360	    const prev = Drawer._lockReleases.get(drawer);
361	    if (prev) prev();
362	    Drawer._lockReleases.set(drawer, release);
363	  }
364	
365	  static releaseLock(drawer: HTMLElement): void {
366	    const release = Drawer._lockReleases.get(drawer);
367	    if (!release) return;
368	    Drawer._lockReleases.delete(drawer);
369	    release();
370	  }
371	
372	  override dispose(): void {
373	    this._magneticCorner?.destroy();
374	    this._magneticCorner = null;
375	    if (this._triggerEl) {
376	      this._triggerEl.removeEventListener("click", this._boundFlipVisibility);
377	      this._triggerEl = null;
378	    }
379	    document.removeEventListener("keydown", this._boundKeydown);
380	
381	    super.dispose();
382	  }
383	}
