6	
7	.no-drawer {
8	  $root: &;
9	
10	  position: fixed;
11	  inset: 0;
12	  z-index: var(--z-index-drawer);
13	  width: 100%;
14	  height: calc(100vh - var(--header-height));
15	  height: calc(
16	    100dvh - var(--header-height)
17	  ); // dvh: iOS 주소창 높이 포함 안 함
18	  top: var(--header-height);
19	  overflow: hidden;
20	  visibility: hidden;
21	  pointer-events: none;
22	
23	  background: var(--clr-ui-bg);
24	
25	  &.is-open {
26	    visibility: visible;
27	    pointer-events: auto;
28	  }
29	
30	  /* 열기 트랜지션 초기값 — GSAP은 to()만 사용 */
31	  &.is-open.is-animating-in {
32	    opacity: 0;
33	  }
34	
35	  &.is-open.is-animating-in &__inner {
36	    opacity: 0;
37	    transform: translateY(24px);
38	  }
39	
40	  /* Barba 전환: 링크 클릭 시 텍스트(inner) 아래로 사라진 뒤 드로어 닫기 */
41	  &.is-barba-leaving &__inner {
42	    transform: translateY(60px);
43	    opacity: 0;
44	    transition:
45	      transform 0.38s ease-out,
46	      opacity 0.32s ease-out;
47	  }
48	
49	  // ---------------------------------------------------------------------------
50	  // Layout — 스크롤은 __inner에서만 (내용이 넘치면 자연스럽게 스크롤)
51	  // ---------------------------------------------------------------------------
52	  &__inner {
53	    position: absolute;
54	    inset: 0;
55	    z-index: 1;
56	    min-height: 0;
57	    height: 100%;
58	    overflow-x: hidden;
59	    overflow-y: auto;
60	    display: flex;
61	    align-items: flex-start;
62	    justify-content: center;
63	    -webkit-overflow-scrolling: touch;
64	    overscroll-behavior-y: contain;
65	  }
66	
67	  &__container {
68	    width: 100%;
69	    margin: 0 auto;
70	    padding-top: var(--gutter-xl);
71	    // 하단: iOS 홈 인디케이터 + 여백 확보
72	    padding-bottom: max(var(--gutter-3xl), env(safe-area-inset-bottom, 0px));
73	  }
74	
75	  &__center {
76	    width: 100%;
77	    display: grid;
78	    grid-template-columns: 8fr 4fr;
